{
  "name": "Simulador Taller en Crisis",
  "description": "An interactive chat simulation for technical training in a factory environment, featuring an AI-powered boss 'Manuel' who assesses students."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Sender {
  User = 'user',
  Boss = 'boss',
  System = 'system',
}

export enum MessageType {
  Text = 'text',
  Hint = 'hint',
  WorkOrder = 'workOrder',
  Report = 'report',
}

export interface Message {
  id: string;
  sender: Sender;
  type: MessageType;
  content: string | React.ReactNode;
  timestamp: number;
}

export interface Question {
  text: string;
  options: {
    A: string;
    B: string;
    C: string;
    D: string;
  };
  correct: string;
  feedback_correct: string;
  feedback_wrong: string;
}

export interface StationData {
  introduction: string;
  questions: Question[];
}

export interface FactoryDataMap {
  [key: string]: StationData;
}

export interface SimulationState {
  isActive: boolean;
  group: string;
  factory: string;
  sessionId: string;
  mood: number;
  stage: number;
  userAnswers: string[];
  answerCorrectness: boolean[];
  isWaitingForAI: boolean;
  isWaitingForHintConfirmation: boolean;
  currentHintQuery: string;
  isFinished: boolean;
}

import { FactoryDataMap } from '../types';

