import { GoogleGenAI } from "@google/genai";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = 'gemini-2.5-flash';

export const generateHint = async (userQuery: string, factory: string): Promise<string> => {
  const prompt = `Eres Manuel, un jefe de taller experto. Un alumno te pide ayuda. Su pregunta es: '${userQuery}'. La estación es '${factory}'.

Tu tarea es decidir si la pregunta es 'Básica' (debería estar en sus apuntes de la presentación teórica) o 'Avanzada' (una duda práctica o compleja).

-   Considera 'Básica': Definiciones (¿qué es un capacitivo?), principios (¿cómo funciona un inductivo?), tipos (PNP/NPN), comparaciones directas (barrera vs difuso).
-   Considera 'Avanzada': Dificultades de aplicación (¿por qué falla con plástico negro brillante?), dudas muy específicas, o algo que no estaría en una introducción.

RESPONDE CON UNO DE ESTOS DOS FORMATOS EXACTOS:

1.  SI ES BÁSICA, escribe:
    Un momento... ¡esto me suena! Esta información es la base de la presentación teórica que os di. Consultar vuestros apuntes os ahorraría los puntos. Pero bueno, os ayudo...
    (Aquí tu pista de 1-2 frases)

2.  SI ES AVANZADA, escribe:
    Entendido. Es una buena pregunta. Aquí va la pista...
    (Aquí tu pista de 1-2 frases)

La pista debe guiarle, no darle la respuesta.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }], // Enable grounding as per original app
      },
    });

    return response.text || "Lo siento, tengo problemas de conexión. Inténtalo de nuevo.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error al contactar con la IA. Inténtalo de nuevo.";
  }
};

export const generateFinalReport = async (
  score: number,
  factory: string,
  summary: string
): Promise<string> => {
  const prompt = `Eres Manuel, jefe de taller, evaluando el informe final de un grupo. Sé directo, conciso y profesional. Habla en plural (vosotros).

DATOS FINALES DE LA SIMULACIÓN:
- PUNTUACIÓN FINAL (ya calculada): ${score} / 4
- Escenario: ${factory}
- Resumen de respuestas:
${summary}

TAREA: Genera un informe estructurado y bien redactado. Sigue estas reglas de formato AL PIE DE LA LETRA:
1.  Los títulos de sección DEBEN estar en mayúsculas y DEBEN incluir el emoji correspondiente (ej: "PUNTOS FUERTES 💪").
2.  El texto DENTRO de cada sección DEBE usar un caso de oración normal y profesional. Esto significa que la primera letra de cada frase (y después de un punto) debe empezar con mayúscula. El resto de la frase irá en minúsculas. NO escribas párrafos enteros en mayúsculas.
3.  Usa el siguiente formato OBLIGATORIO:
    PUNTUACIÓN FINAL: ${score} / 4
    PUNTOS FUERTES 💪: (Tu texto aquí, usando caso de oración normal. Menciona los aciertos)
    OPORTUNIDADES DE MEJORA 🛠️: (Tu texto aquí, usando caso de oración normal. Menciona los fallos)
    CONSEJO DEL JEFE 👨‍🔧: (Tu texto aquí, usando caso de oración normal)
4.  INCENTIVO: BASADO EN LA PUNTUACIÓN PROPORCIONADA, aplica ESTRICTAMENTE esta regla:
    - Si la puntuación es 4 (4 aciertos), añade: "Un trabajo impecable. Gracias a vuestra eficiencia, habéis ganado el bono. Os propondré para un ascenso. ¡Enhorabuena! 🚀".
    - Si la puntuación es 3 (3 aciertos), añade: "¡Muy buen trabajo! Casi perfecto. Habéis ganado un bono para el equipo. ¡Seguid así! 🏆".
    - Para cualquier otra puntuación, NO añadas ningún incentivo.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
    });

    return response.text || "No se pudo generar el informe final.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error generando el informe.";
  }
};

// Constants for Google Form
const REALTIME_FORM_ACTION_URL = "https://docs.google.com/forms/d/e/1FAIpQLSdZI8DzQ4baj-Sl8oDuNVnkIfjds8o3n1HDmuwXD3dKScquqQ/formResponse";
const SESSION_ID_FIELD = "entry.1378149903";
const GROUP_FIELD = "entry.66122651";
const FACTORY_FIELD = "entry.1367589106";
const QUESTION_NUM_FIELD = "entry.2021368631";
const ANSWER_TEXT_FIELD = "entry.400534341";
const FINAL_FEEDBACK_FIELD = "entry.1677109584";
const SCORE_FIELD = "entry.55841423";

interface SubmissionData {
  sessionId: string;
  group: string;
  factory: string;
  question?: string;
  answer?: string;
  score?: string;
  finalFeedback?: string;
}

export const sendRealTimeUpdate = async (data: SubmissionData) => {
  const formData = new FormData();
  formData.append(SESSION_ID_FIELD, data.sessionId);
  formData.append(GROUP_FIELD, data.group);
  formData.append(FACTORY_FIELD, data.factory);

  if (data.question) formData.append(QUESTION_NUM_FIELD, data.question);
  if (data.answer) formData.append(ANSWER_TEXT_FIELD, data.answer);
  if (data.score) formData.append(SCORE_FIELD, data.score);
  if (data.finalFeedback) formData.append(FINAL_FEEDBACK_FIELD, data.finalFeedback);

  try {
    await fetch(REALTIME_FORM_ACTION_URL, {
      method: 'POST',
      body: formData,
      mode: 'no-cors'
    });
    // Since mode is no-cors, we can't really read the response, but it submits.
    return true;
  } catch (error) {
    console.error('Error sending real-time update:', error);
    return false;
  }
};

import React from 'react';

interface MoodBarProps {
  mood: number;
}

const moodLevels: Record<number, { text: string; color: string; width: string }> = {
  5: { text: 'Excelente', color: 'bg-green-500', width: '100%' },
  4: { text: 'Bien', color: 'bg-lime-500', width: '80%' },
  3: { text: 'Serio', color: 'bg-yellow-500', width: '60%' },
  2: { text: 'Molesto', color: 'bg-orange-500', width: '40%' },
  1: { text: 'Furioso', color: 'bg-red-600', width: '20%' },
};

export const MoodBar: React.FC<MoodBarProps> = ({ mood }) => {
  const currentMood = moodLevels[mood] || moodLevels[3];

  return (
    <div className="p-2 bg-gray-200 border-b border-gray-300">
      <div className="w-full bg-gray-300 rounded-full h-2.5">
        <div
          className={`h-2.5 rounded-full transition-all duration-500 ease-in-out ${currentMood.color}`}
          style={{ width: currentMood.width }}
        />
      </div>
      <p className="text-center text-sm font-semibold mt-1 text-gray-700">
        Estado de Ánimo: {currentMood.text}
      </p>
    </div>
  );
};

import React from 'react';
import { Message, Sender, MessageType } from '../types';

interface ChatBubbleProps {
  message: Message;
}

export const ChatBubble: React.FC<ChatBubbleProps> = ({ message }) => {
  const isUser = message.sender === Sender.User;
  const isSystem = message.sender === Sender.System;
  const isHint = message.type === MessageType.Hint;
  const isReport = message.type === MessageType.Report;

  // Base classes
  let bubbleClass = "p-3 rounded-lg max-w-[90%] md:max-w-md shadow-sm break-words";
  let containerClass = "flex w-full mb-3";

  if (isUser) {
    bubbleClass += " bg-[#dcf8c6] text-gray-800 rounded-tr-none";
    containerClass += " justify-end";
  } else if (isSystem) {
    bubbleClass += " bg-white text-gray-800 border border-gray-200";
    containerClass += " justify-start";
  } else if (isHint) {
    bubbleClass += " bg-amber-50 text-amber-900 border-l-4 border-amber-500 rounded-tl-none";
    containerClass += " justify-start";
  } else {
    // Standard boss message
    bubbleClass += " bg-white text-gray-800 border border-gray-200 rounded-tl-none";
    containerClass += " justify-start";
  }

  // Handle special HTML content (like reports or work orders)
  const isHtml = typeof message.content === 'string' && (isReport || message.type === MessageType.WorkOrder || message.content.includes('<'));

  return (
    <div className={containerClass}>
      <div className={bubbleClass}>
        {isHtml ? (
           <div 
             className="text-sm md:text-base space-y-2"
             dangerouslySetInnerHTML={{ __html: message.content as string }} 
           />
        ) : (
           <div className="text-sm md:text-base whitespace-pre-wrap">{message.content}</div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';

interface EntryModalProps {
  onStart: (group: string, factory: string) => void;
}

const GROUPS = ["Grupo A", "Grupo B", "Grupo C", "Grupo D"];
const FACTORIES = [
  "Lácteos del Sur (Línea de Envasado)",
  "Motores A-Zul (Brazo Robótico)",
  "Vinos Sierra Morena (Encapsuladora)",
  "PACSA (Línea de Pesado)",
  "Logística Sur-Ex (Transportador Almacenaje)"
];

export const EntryModal: React.FC<EntryModalProps> = ({ onStart }) => {
  const [group, setGroup] = useState("");
  const [factory, setFactory] = useState("");

  const handleStart = () => {
    if (group && factory) {
      onStart(group, factory);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm px-4">
      <div className="bg-white p-6 md:p-8 rounded-xl shadow-2xl text-center w-full max-w-md">
        <h2 className="text-2xl font-bold mb-4 text-gray-800">Inicio de la Simulación</h2>
        <p className="mb-6 text-gray-600">Selecciona tu grupo y la estación de trabajo asignada.</p>

        <div className="text-left mb-4">
          <label htmlFor="student-group-select" className="block font-semibold text-gray-700 mb-1">Grupo:</label>
          <div className="relative">
            <select 
              id="student-group-select" 
              value={group}
              onChange={(e) => setGroup(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 bg-white appearance-none"
            >
              <option value="">-- Selecciona tu grupo --</option>
              {GROUPS.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700">
              <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
            </div>
          </div>
        </div>

        <div className="text-left mb-6">
          <label htmlFor="factory-select" className="block font-semibold text-gray-700 mb-1">Fábrica / Estación:</label>
          <div className="relative">
            <select 
              id="factory-select" 
              value={factory}
              onChange={(e) => setFactory(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 bg-white appearance-none"
            >
              <option value="">-- Selecciona una fábrica --</option>
              {FACTORIES.map(f => <option key={f} value={f}>{f}</option>)}
            </select>
             <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700">
              <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
            </div>
          </div>
        </div>

        <button 
          onClick={handleStart}
          disabled={!group || !factory}
          className="w-full bg-teal-600 text-white font-bold py-3 px-4 rounded-lg hover:bg-teal-700 transition-colors disabled:bg-gray-400 disabled:cursor-not-allowed shadow-md active:transform active:scale-95"
        >
          Comenzar Simulación
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Message, Sender, MessageType, SimulationState } from './types';
import { FACTORY_DATA } from './data/factoryData';
import { EntryModal } from './components/EntryModal';
import { ChatBubble } from './components/ChatBubble';
import { MoodBar } from './components/MoodBar';
import { generateHint, generateFinalReport } from './services/geminiService';
import { sendRealTimeUpdate } from './services/formService';

const BOSS_AVATAR = "https://raw.githubusercontent.com/angelgabrieldiazcampos-droid/Classroom/main/Manuel.png";

export default function App() {
  const [state, setState] = useState<SimulationState>({
    isActive: false,
    group: "",
    factory: "",
    sessionId: "",
    mood: 3,
    stage: 0,
    userAnswers: [],
    answerCorrectness: [],
    isWaitingForAI: false,
    isWaitingForHintConfirmation: false,
    currentHintQuery: "",
    isFinished: false,
  });

  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState("");
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const addMessage = (content: string | React.ReactNode, sender: Sender, type: MessageType = MessageType.Text) => {
    setMessages(prev => [...prev, {
      id: Date.now().toString() + Math.random().toString(),
      sender,
      type,
      content,
      timestamp: Date.now()
    }]);
  };

  const handleStart = (group: string, factory: string) => {
    const sessionId = `${Date.now()}-${group.replace(/\s/g, '')}`;
    setState(prev => ({
      ...prev,
      isActive: true,
      group,
      factory,
      sessionId
    }));

    const station = FACTORY_DATA[factory];
    addMessage(station.introduction, Sender.Boss);

    setTimeout(() => {
      const firstQ = station.questions[0];
      addMessage(formatQuestion(firstQ), Sender.Boss);
    }, 2000);
  };

  const formatQuestion = (q: any) => {
    return `
      <div class="font-bold mb-2">${q.text}</div>
      <div class="ml-2 mb-1"><strong>A.</strong> ${q.options.A}</div>
      <div class="ml-2 mb-1"><strong>B.</strong> ${q.options.B}</div>
      <div class="ml-2 mb-1"><strong>C.</strong> ${q.options.C}</div>
      <div class="ml-2 mb-1"><strong>D.</strong> ${q.options.D}</div>
    `;
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || state.isWaitingForAI) return;

    const text = inputValue.trim();
    setInputValue("");
    addMessage(text, Sender.User);

    const normalizedAnswer = text.toUpperCase();

    // 1. Hint Confirmation Logic
    if (state.isWaitingForHintConfirmation) {
      if (['SI', 'SÍ', 'YES', 'S'].includes(normalizedAnswer)) {
        setState(prev => ({ ...prev, isWaitingForAI: true, isWaitingForHintConfirmation: false }));
        addMessage("Aceptado. Os costará 0,25 puntos. Déjame pensar...", Sender.Boss);

        // Penalize
        sendRealTimeUpdate({
          sessionId: state.sessionId,
          group: state.group,
          factory: state.factory,
          question: `PISTA_Q${state.stage + 1}`,
          answer: 'Solicitó pista',
          score: '-0,25'
        });

        // Decrease mood
        const newMood = Math.max(1, state.mood - 1);
        setState(prev => ({ ...prev, mood: newMood }));

        // Call AI
        const hint = await generateHint(state.currentHintQuery, state.factory);
        addMessage(`👨‍🔧 <strong>Pista de Manuel:</strong> ${hint}`, Sender.Boss, MessageType.Hint);
        setState(prev => ({ ...prev, isWaitingForAI: false }));

      } else {
        setState(prev => ({ ...prev, isWaitingForHintConfirmation: false }));
        addMessage("Entendido. Continuad cuando estéis listos.", Sender.Boss);
      }
      return;
    }

    // 2. Answer Logic (A, B, C, D)
    if (['A', 'B', 'C', 'D'].includes(normalizedAnswer)) {
       const currentQuestion = FACTORY_DATA[state.factory].questions[state.stage];
       const isCorrect = normalizedAnswer === currentQuestion.correct;
       const feedback = isCorrect ? currentQuestion.feedback_correct : currentQuestion.feedback_wrong;
       const score = isCorrect ? '1' : '0';

       // Update State locally
       const nextStage = state.stage + 1;
       const nextUserAnswers = [...state.userAnswers];
       nextUserAnswers[state.stage] = text;
       const nextCorrectness = [...state.answerCorrectness];
       nextCorrectness[state.stage] = isCorrect;

       const nextMood = isCorrect ? Math.min(5, state.mood + 1) : Math.max(1, state.mood - 1);

       setState(prev => ({
         ...prev,
         stage: nextStage,
         userAnswers: nextUserAnswers,
         answerCorrectness: nextCorrectness,
         mood: nextMood
       }));

       // Send to form
       sendRealTimeUpdate({
         sessionId: state.sessionId,
         group: state.group,
         factory: state.factory,
         question: `Q${state.stage + 1}`,
         answer: text,
         score
       });

       addMessage(feedback, Sender.Boss);

       // Check if more questions or finish
       if (nextStage < 4) {
         setTimeout(() => {
            const nextQ = FACTORY_DATA[state.factory].questions[nextStage];
            addMessage(formatQuestion(nextQ), Sender.Boss);
         }, 2500);
       } else {
         setTimeout(() => {
           addMessage("Diagnóstico completo. Buen trabajo, equipo. Pulsa 'Finalizar y Enviar' para recibir el informe.", Sender.System);
           setState(prev => ({ ...prev, isFinished: true }));
         }, 1500);
       }
    } else {
      // 3. Hint Request Logic (Anything not A, B, C, D)
      setState(prev => ({ 
        ...prev, 
        isWaitingForHintConfirmation: true, 
        currentHintQuery: text 
      }));
      addMessage("Parece que necesitáis ayuda. Puedo daros una pista, pero os costará **0,25 puntos** de la nota final. ¿Aceptáis? (Escribe 'Si' o 'No')", Sender.Boss);
    }
  };

  const handleFinalize = async () => {
    setState(prev => ({ ...prev, isWaitingForAI: true }));

    // Calculate final score
    const correctCount = state.answerCorrectness.filter(Boolean).length;

    // Build summary
    let summary = "";
    const station = FACTORY_DATA[state.factory];
    station.questions.forEach((q, idx) => {
       summary += `Q${idx+1}: ${state.answerCorrectness[idx] ? 'Correcta' : 'Incorrecta'}. (Respuesta: '${state.userAnswers[idx] || 'N/A'}', Correcta: '${q.correct}')\n`;
    });

    const reportText = await generateFinalReport(correctCount, state.factory, summary);

    // Render report HTML
    const reportHtml = formatFinalReport(reportText);
    addMessage(reportHtml, Sender.Boss, MessageType.Report);

    // Generate Work Order
    const workOrderHtml = generateWorkOrder(state.factory, state.group, correctCount, state.userAnswers, state.answerCorrectness);
    addMessage(workOrderHtml, Sender.System, MessageType.WorkOrder);

    // Submit final
    await sendRealTimeUpdate({
      sessionId: state.sessionId,
      group: state.group,
      factory: state.factory,
      finalFeedback: reportText
    });

    addMessage("✅ Informe final enviado correctamente.", Sender.System);
    setState(prev => ({ ...prev, isWaitingForAI: false })); // Keep finished state true
  };

  const formatFinalReport = (text: string) => {
    const parts = text.split(/PUNTOS FUERTES 💪:|OPORTUNIDADES DE MEJORA 🛠️:|CONSEJO DEL JEFE 👨‍🔧:/i);
    // Rough parsing based on expected Gemini output
    let html = `<div class="p-2">
      <h3 class="text-xl font-bold text-gray-800 mb-4 text-center border-b pb-2">INFORME DE EVALUACIÓN</h3>`;

    const scoreMatch = text.match(/PUNTUACIÓN FINAL: ([\d,.]+\s*\/\s*4)/i);
    if (scoreMatch) {
       html += `<div class="text-center my-4"><p class="text-gray-600 text-sm font-medium">Puntuación Final</p><p class="text-5xl md:text-6xl font-bold text-teal-600">${scoreMatch[1].trim()}</p></div>`;
    }

    // Since splitting by exact regex might be fragile if model varies slightly, we can display the text blocks if regex fails,
    // but assuming model follows instruction:
    if (parts.length > 1) {
       if (parts[1]?.trim()) html += `<div class="my-4"><h4 class="font-semibold text-lg text-green-700 flex items-center gap-2 mb-1">💪 PUNTOS FUERTES</h4><p class="text-gray-700 pl-2 border-l-2 border-green-200">${parts[1].trim().replace(/\n/g, '<br>')}</p></div>`;
       if (parts[2]?.trim()) html += `<div class="my-4"><h4 class="font-semibold text-lg text-orange-600 flex items-center gap-2 mb-1">🛠️ OPORTUNIDADES DE MEJORA</h4><p class="text-gray-700 pl-2 border-l-2 border-orange-200">${parts[2].trim().replace(/\n/g, '<br>')}</p></div>`;
       if (parts[3]?.trim()) html += `<div class="my-4"><h4 class="font-semibold text-lg text-blue-600 flex items-center gap-2 mb-1">👨‍🔧 CONSEJO DEL JEFE</h4><p class="text-gray-700 pl-2 border-l-2 border-blue-200">${parts[3].trim().replace(/\n/g, '<br>')}</p></div>`;
    } else {
        // Fallback: simple text display with bolding
        html += `<div class="whitespace-pre-wrap">${text}</div>`;
    }

    const incentiveMatch = text.match(/Un trabajo impecable.*|¡Muy buen trabajo!.*Casi perfecto.*/si);
    if (incentiveMatch) {
        html += `<div class="mt-5 p-3 bg-amber-100 border-l-4 border-amber-500 rounded-r-lg shadow-inner"><p class="font-semibold text-amber-800">${incentiveMatch[0].trim()}</p></div>`;
    }

    html += `</div>`;
    return html;
  };

  const generateWorkOrder = (factory: string, group: string, correctCount: number, answers: string[], correctness: boolean[]) => {
      const station = FACTORY_DATA[factory];
      let qHtml = "";
      station.questions.forEach((q, idx) => {
          const userAnswer = answers[idx] || "N/A";
          const isCorrect = correctness[idx];
          const icon = isCorrect ? '✅' : '❌';
          qHtml += `
            <div class="border-b pb-2 mb-2 last:border-0">
                <p class="font-semibold text-gray-800 text-sm">${q.text}</p>
                <p class="text-xs text-gray-600 mt-1">Tu respuesta: <span class="font-medium ${isCorrect ? 'text-green-600' : 'text-red-600'}">${icon} (${userAnswer})</span></p>
                <p class="text-xs text-blue-700">Respuesta Correcta: <span class="font-semibold">(${q.correct}) ${q.options[q.correct as keyof typeof q.options]}</span></p>
            </div>
          `;
      });

      return `
        <div class="p-2">
            <h3 class="text-xl font-bold text-gray-800 mb-2 text-center border-b pb-2">ORDEN DE TRABAJO</h3>
            <div class="text-sm mb-3 grid grid-cols-1 gap-1 bg-gray-50 p-2 rounded">
                <p><strong>Estación:</strong> ${factory}</p>
                <p><strong>Grupo:</strong> ${group}</p>
                <p><strong>Resultado:</strong> ${correctCount} de 4 respuestas correctas.</p>
            </div>
            <h4 class="font-bold text-gray-800 mb-2 text-sm uppercase tracking-wide">Resumen de Verificación:</h4>
            ${qHtml}
            <div class="mt-4 text-center border-t pt-2">
                <p class="text-gray-700 font-semibold text-sm">Validado por:</p>
                <p class="text-teal-700 text-2xl font-bold italic" style="font-family: 'Brush Script MT', cursive;">Manuel</p>
                <p class="text-xs text-gray-500">(Jefe de Taller)</p>
            </div>
        </div>
      `;
  };

  if (!state.isActive) {
    return <EntryModal onStart={handleStart} />;
  }

  return (
    <div className="flex items-center justify-center min-h-screen p-4 md:p-6" style={{
        backgroundImage: `url('https://i.pinimg.com/736x/8c/98/99/8c98994518b575bfd8c949e91d20548b.jpg')`,
        backgroundRepeat: 'repeat',
        backgroundSize: '300px'
    }}>
      <div className="w-full max-w-2xl mx-auto bg-white rounded-2xl shadow-2xl flex flex-col h-[85vh] md:h-[800px] border border-gray-300 overflow-hidden backdrop-blur-sm bg-opacity-95">

        {/* Header */}
        <header className="bg-teal-700 text-white p-3 md:p-4 flex items-center gap-4 border-b border-teal-800 shadow-md z-10">
          <img src={BOSS_AVATAR} alt="Avatar Jefe" className="w-12 h-12 rounded-full object-cover border-2 border-white/50 shadow-sm" />
          <div>
            <h1 className="text-lg font-bold tracking-wide">Manuel Jefe</h1>
            <p className="text-xs text-teal-100 flex items-center gap-1">
               <span className={`w-2 h-2 rounded-full ${state.isWaitingForAI ? 'bg-amber-400 animate-pulse' : 'bg-green-400'}`}></span>
               {state.isWaitingForAI ? 'escribiendo...' : 'en línea'}
            </p>
          </div>
        </header>

        {/* Mood Bar */}
        <MoodBar mood={state.mood} />

        {/* Chat Window */}
        <main className="flex-1 p-4 overflow-y-auto flex flex-col gap-2 bg-[#e5ddd5] bg-opacity-30 relative scroll-smooth">
             {messages.map((msg) => (
               <ChatBubble key={msg.id} message={msg} />
             ))}
             <div ref={chatEndRef} />
        </main>

        {/* Input Area */}
        <footer className="bg-gray-100 p-3 md:p-4 border-t border-gray-200">
           {!state.isFinished ? (
               <div className="flex items-center gap-2">
                 <input 
                   type="text" 
                   value={inputValue}
                   onChange={(e) => setInputValue(e.target.value)}
                   onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                   disabled={state.isWaitingForAI}
                   className="flex-1 p-3 border border-gray-300 rounded-full focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent transition-shadow shadow-inner"
                   placeholder="Escribe tu respuesta (A, B, C o D)..."
                 />
                 <button 
                   onClick={handleSendMessage}
                   disabled={state.isWaitingForAI || !inputValue.trim()}
                   className="bg-teal-600 text-white rounded-full p-3 hover:bg-teal-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-md active:scale-95"
                 >
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"></line><polygon points="22 2 15 22 11 13 2 9 22 2"></polygon></svg>
                 </button>
               </div>
           ) : (
               <div className="flex justify-center">
                 <button 
                   onClick={handleFinalize}
                   disabled={state.isWaitingForAI} // Reuse waiting flag for submission
                   className="w-full md:w-auto bg-green-600 hover:bg-green-700 text-white rounded-lg py-3 px-8 font-semibold transition-all hover:scale-105 flex items-center justify-center gap-2 shadow-lg disabled:bg-gray-400 disabled:scale-100 disabled:cursor-not-allowed"
                 >
                    {state.isWaitingForAI ? (
                        <>
                           <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                           <span>Evaluando...</span>
                        </>
                    ) : (
                        "Finalizar y Enviar"
                    )}
                 </button>
               </div>
           )}
        </footer>
      </div>
    </div>
  );
}

